  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Tinidazole has absolute oral bioavailability >90% in humans after oral tablets, directly supporting high F for the query given its high transfer score.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Ondansetron absolute oral bioavailability was 0.65 ± 0.26 in 12 subjects, a direct human absolute measurement supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Bumetanide oral bioavailability was 83.7 ± 12.4% in fasting healthy volunteers versus IV, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Tolfenamic acid absolute oral bioavailability was 63.2% in healthy female volunteers after a 100 mg oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Fleroxacin showed 100% absolute oral bioavailability in early human pharmacokinetic studies, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "S-vigabatrin oral bioavailability was >49% in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved human absolute/relative bioavailability records for highly transferable analogues report F values well above 20% (50–100%), with no contradictory low-bioavailability evidence; therefore the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental measurement of the query molecule's absolute oral bioavailability was retrieved; prediction relies on transferable analogues.",
    "The query is a sulfonate-containing pyrazolone prodrug; the retrieved analogues are not prodrugs, leaving some uncertainty about parent versus active-metabolite bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

